BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Section 741 general capital gain on sale with no hot assets
(3, 'Partnerships', 'Partner Caldwell sells her 25% interest in Sunridge Partners LP for $300,000. Her outside basis is $220,000. The partnership holds no hot assets under Section 751. Under Section 741, what is the character of Caldwell''s $80,000 gain?', '["Capital gain", "Ordinary income", "50% capital gain and 50% ordinary income", "Tax-exempt income"]'::jsonb, 0, 'Under IRC Section 741, gain or loss from the sale of a partnership interest is treated as gain or loss from the sale of a capital asset. Because Sunridge holds no hot assets under Section 751, Caldwell''s entire $80,000 gain is capital gain. If the partnership held unrealized receivables or inventory, Section 751 would recharacterize the portion attributable to those hot assets as ordinary income.', 'medium', 2),

-- Q2: medium / L3 — Nonrecourse deductions allocated by profit-sharing ratios
(3, 'Partnerships', 'Birchwood Partners LP has two equal partners, Kline and Morris. The partnership borrows $400,000 on a nonrecourse basis secured solely by partnership property and uses the proceeds to purchase depreciable equipment. In Year 1, the partnership claims $80,000 of depreciation that creates partnership minimum gain. How must the $80,000 of nonrecourse deductions be allocated?', '["Entirely to the partner with the highest marginal tax rate", "In accordance with the partners'' profit-sharing ratios—$40,000 to each partner", "Entirely to the partner who negotiated the nonrecourse loan", "In proportion to each partner''s capital contributions"]'::jsonb, 1, 'Under Treas. Reg. Section 1.704-2(e), nonrecourse deductions must be allocated in accordance with the partners'' interests in partnership profits (typically their profit-sharing ratios). Since Kline and Morris share profits equally, each receives $40,000. Allocating nonrecourse deductions based on tax rates or based on who arranged the loan is not permitted—the regulations mandate profit-ratio allocation.', 'medium', 3),

-- Q3: easy / L1 — Capital account definition
(3, 'Partnerships', 'In partnership taxation, what is a partner''s capital account?', '["The partner''s share of partnership liabilities", "The partner''s individual bank account used for partnership transactions", "A record that tracks a partner''s equity in the partnership based on contributions, distributions, and allocated income or loss", "The total cash the partner has contributed over time"]'::jsonb, 2, 'Under Treas. Reg. Section 1.704-1(b)(2)(iv), a partner''s capital account tracks their equity stake in the partnership. It is increased by contributions and allocated income, and decreased by distributions and allocated losses. A capital account differs from outside basis because it does not include the partner''s share of partnership liabilities.', 'easy', 1),

-- Q4: medium / L3 — Transitory allocations failing substantiality
(3, 'Partnerships', 'Ridgeline Partners LP allocates all $50,000 of Year 1 depreciation to Partner Graves (a high-bracket taxpayer) and all $50,000 of Year 2 gain from selling the same asset to Partner Foley (a low-bracket taxpayer). Both partners have equal 50% interests and equal capital accounts after the two-year cycle. Under Section 704(b), how should the IRS treat this allocation?', '["It is respected because the net effect on capital accounts is correct", "It is respected because a valid business purpose exists", "It is respected if it follows an arm''s-length standard", "It is disregarded as a transitory allocation that lacks substantiality"]'::jsonb, 3, 'Under IRC Section 704(b) and Treas. Reg. Section 1.704-1(b)(2)(iii)(c), a transitory allocation shifts tax benefits between partners without substantially affecting the amounts they receive economically. Because the depreciation deduction to Graves and the offsetting gain to Foley cancel out in capital accounts, the allocation lacks substantiality and will be reallocated according to the partners'' interests in the partnership.', 'medium', 3),

-- Q5: medium / L3 — Limited partner SE tax exemption
(3, 'Partnerships', 'Partner Hatcher is a limited partner in Crestview Partners LP and does not perform any services for the partnership. Her distributive share of partnership ordinary income is $75,000, and she receives a $10,000 guaranteed payment for the use of capital. What amount is subject to Hatcher''s self-employment tax?', '["$0", "$75,000", "$85,000", "$10,000"]'::jsonb, 3, 'Under IRC Section 1402(a)(13), a limited partner''s distributive share of partnership income is generally excluded from self-employment tax. However, guaranteed payments under Section 707(c) for services or use of capital are always subject to self-employment tax regardless of partner status. Therefore, only Hatcher''s $10,000 guaranteed payment is subject to SE tax, not her $75,000 distributive share.', 'medium', 3),

-- Q6: easy / L1 — Profits interest definition
(3, 'Partnerships', 'In partnership taxation, what is a profits interest?', '["An interest entitling the holder to a share of only the partnership''s existing capital", "A guaranteed annual payment for management services", "An interest entitling the holder to a share of future partnership profits but not existing capital", "A distribution of previously earned income to a retiring partner"]'::jsonb, 2, 'Under Rev. Proc. 93-27, a profits interest is a partnership interest that gives the holder a right to share in future profits and appreciation but has no claim to the partnership''s existing capital at the time of issuance. This differs from a capital interest, which would entitle the holder to a share of partnership assets if the partnership liquidated immediately after the grant.', 'easy', 1),

-- Q7: hard / L4 — Remedial allocation method vs traditional method under Section 704(c)
(3, 'Partnerships', 'Sutton contributes equipment with a basis of $40,000 and FMV of $100,000 to an equal two-person partnership with Vargas, who contributes $100,000 cash. The equipment has 5 years of remaining life. Under the traditional method, Vargas receives only $8,000 annual tax depreciation ($40,000 basis over 5 years) despite $20,000 of book depreciation. Evaluate what the remedial allocation method achieves that the traditional method cannot.', '["It increases the partnership''s total tax depreciation above $40,000", "It shifts all depreciation to Sutton as the contributing partner", "It allows Vargas to take a FMV basis of $100,000 in the equipment", "It eliminates the ceiling rule by creating offsetting notional items—additional depreciation to Vargas and matching ordinary income to Sutton"]'::jsonb, 3, 'Under Treas. Reg. Section 1.704-3(d), the remedial allocation method eliminates the ceiling rule distortion by creating notional tax items. It allocates additional depreciation deductions to Vargas (noncontributing partner) to match book depreciation, with an equal amount of offsetting ordinary income to Sutton (contributing partner). The traditional method cannot fully compensate Vargas because actual tax depreciation is limited to the $40,000 carryover basis.', 'hard', 4),

-- Q8: medium / L3 — Marketable securities treated as money under Section 731(c)
(3, 'Partnerships', 'Partner Ingram has an outside basis of $50,000. The partnership distributes publicly traded stock with an FMV of $70,000 and an inside basis of $30,000 to Ingram in a current distribution. Under Section 731(c), how much gain must Ingram recognize?', '["$20,000 capital gain", "No gain because property distributions do not trigger recognition", "$40,000 capital gain", "$70,000 ordinary income"]'::jsonb, 0, 'Under IRC Section 731(c), marketable securities distributed by a partnership are treated as money for purposes of Section 731(a). The $70,000 FMV exceeds Ingram''s $50,000 outside basis by $20,000, triggering capital gain recognition. Without Section 731(c), property distributions generally do not create gain, but Congress enacted this provision to prevent partnerships from distributing liquid marketable assets tax-free.', 'medium', 3),

-- Q9: easy / L1 — Partnership required taxable year
(3, 'Partnerships', 'Under Section 706(b), what is the first test for determining a partnership''s required taxable year?', '["The partnership must always use a fiscal year ending June 30", "The taxable year of the partners owning a majority interest in profits and capital", "A 52-53-week taxable year", "Any taxable year the managing partner selects"]'::jsonb, 1, 'Under IRC Section 706(b)(1)(B), a partnership must generally adopt the taxable year of partners holding a majority interest (more than 50% of profits and capital). If no majority interest taxable year exists, the partnership uses the year of all principal partners; if that test also fails, it defaults to the year producing the least aggregate deferral. A partnership cannot freely choose any year.', 'easy', 1),

-- Q10: easy / L1 — Section 754 election filing procedure
(3, 'Partnerships', 'How does a partnership make a Section 754 election?', '["By filing an amended Form 1065 for the prior year", "By notifying each partner individually in writing", "By attaching a written statement to the partnership''s timely filed Form 1065 for the year the election takes effect", "By filing Form 8832 with the IRS"]'::jsonb, 2, 'Under IRC Section 754 and Treas. Reg. Section 1.754-1(b), a partnership makes the election by attaching a written statement to the Form 1065 filed for the taxable year in which the election applies. Once made, the election applies to all subsequent transfers and distributions until revoked with IRS consent. Form 8832 is used for entity classification elections, not Section 754 elections.', 'easy', 1),

-- Q11: easy / L1 — General partners subject to SE tax on distributive share
(3, 'Partnerships', 'Under IRC Section 1402, which partners are generally subject to self-employment tax on their distributive share of partnership ordinary income?', '["Only partners who receive guaranteed payments", "Only partners who contribute more than 50% of capital", "Only limited partners", "General partners"]'::jsonb, 3, 'Under IRC Section 1402(a), a general partner''s distributive share of partnership ordinary trade or business income is included in net earnings from self-employment and subject to self-employment tax. Section 1402(a)(13) exempts limited partners'' distributive shares. However, guaranteed payments for services are always subject to SE tax regardless of whether the partner is general or limited.', 'easy', 1),

-- Q12: hard / L4 — Contribution of encumbered property where liability exceeds basis
(3, 'Partnerships', 'Partner Thornton contributes land with an adjusted basis of $60,000 and FMV of $250,000 to an equal two-person partnership. The land is subject to a $150,000 recourse mortgage that the partnership assumes. After the contribution, Thornton''s share of the $150,000 liability is $75,000 (50%). Evaluate Thornton''s outside basis and any gain recognized.', '["Outside basis of $60,000; no gain recognized", "Outside basis of $0; no gain recognized", "Outside basis of $135,000; no gain recognized", "Outside basis of $0; $15,000 gain recognized"]'::jsonb, 3, 'Under IRC Section 752(b), the portion of liability shifted to the other partner ($75,000) is treated as a deemed cash distribution to Thornton. Thornton''s basis calculation: $60,000 (property basis) + $75,000 (retained liability share) - $150,000 (total liability relief) = negative $15,000, floored at $0 with $15,000 recognized as capital gain under Section 731(a). The gain arises because the net liability relief exceeds Thornton''s property basis.', 'hard', 4),

-- Q13: hard / L3 — Basis step-down under Section 743(b)
(3, 'Partnerships', 'Oakmont Partners LP has a Section 754 election in effect. Partner Shelby purchases a 20% interest from an existing partner for $100,000. The partnership''s total inside basis in its assets is $700,000 (Shelby''s 20% share = $140,000). What is the Section 743(b) adjustment?', '["$40,000 step-up allocated among partnership assets", "$40,000 step-down allocated among partnership assets", "$100,000 step-up allocated among partnership assets", "$0 because the adjustment only applies when a step-up is required"]'::jsonb, 1, 'Under IRC Section 743(b), the adjustment equals the transferee''s outside basis minus their proportionate share of inside basis: $100,000 - $140,000 = negative $40,000. This produces a $40,000 basis step-down allocated among partnership assets with respect to Shelby only. A step-down occurs when the purchase price is below the buyer''s share of inside basis, and the adjustment is not limited to step-ups.', 'hard', 3),

-- Q14: easy / L2 — Suspended basis-limited losses carry forward indefinitely
(3, 'Partnerships', 'Partner Chambers has an outside basis of $20,000. Her distributive share of partnership ordinary loss is $35,000. Chambers deducts $20,000 (limited to her basis). What happens to the remaining $15,000 loss?', '["It is permanently disallowed", "It is deducted on the partnership''s Form 1065", "It is suspended and carried forward indefinitely until Chambers has sufficient basis to deduct it", "It converts to a capital loss"]'::jsonb, 2, 'Under IRC Section 704(d), a partner cannot deduct losses exceeding their outside basis. The $15,000 excess is not permanently lost—it is suspended and carried forward to future years. When Chambers''s outside basis increases through income allocations, contributions, or increased liability share, the suspended loss becomes deductible. Unlike net operating losses, there is no expiration period for basis-limited suspended partnership losses.', 'easy', 2),

-- Q15: easy / L1 — Minimum number of partners
(3, 'Partnerships', 'What is the minimum number of members required to form a partnership for federal tax purposes?', '["Two", "Three", "One", "Five"]'::jsonb, 0, 'Under IRC Section 761(a), a partnership is defined as an association of two or more persons carrying on a business as co-owners for profit. A single individual cannot form a partnership; a single-member LLC is instead treated as a disregarded entity for federal tax purposes unless it elects corporate treatment under the check-the-box regulations (Treas. Reg. Section 301.7701-3).', 'easy', 1),

-- Q16: easy / L1 — "Interests in the partnership" reallocation standard
(3, 'Partnerships', 'Under Section 704(b), if a special allocation lacks substantial economic effect, how does the IRS reallocate the item?', '["Equally among all partners regardless of their interests", "According to the partner who contributed the most capital", "Based on each partner''s individual tax rate", "According to the partners'' interests in the partnership, determined under all facts and circumstances"]'::jsonb, 3, 'Under IRC Section 704(b) and Treas. Reg. Section 1.704-1(b)(3), when a special allocation fails the substantial economic effect test, the IRS reallocates the item based on the partners'' interests in the partnership. This is a facts-and-circumstances determination considering how partners share economic benefits and burdens of the partnership, including contributions, profit sharing, and liquidation rights.', 'easy', 1),

-- Q17: medium / L3 — Qualified income offset as alternative to DRO
(3, 'Partnerships', 'Elm Street Partners LP allows Partner Dawson to receive allocations that reduce her capital account below zero but does not require Dawson to restore a deficit balance upon liquidation. Instead, the partnership agreement includes a qualified income offset provision. In Year 1, Dawson''s capital account reaches negative $15,000. Apply the qualified income offset to determine the result.', '["Dawson must contribute $15,000 cash to restore the deficit", "The partnership must allocate the first $15,000 of gross income to Dawson to eliminate the deficit as quickly as possible", "The deficit is forgiven and no further action is required", "The partnership must distribute $15,000 to other partners to offset Dawson''s deficit"]'::jsonb, 1, 'Under Treas. Reg. Section 1.704-1(b)(2)(ii)(d), a qualified income offset requires the partnership to allocate items of income and gain to a partner with an unexpected capital account deficit as quickly as possible to eliminate that deficit. This serves as an alternative to a deficit restoration obligation and preserves economic effect for the allocation. Without either provision, allocations creating the deficit would lack economic effect.', 'medium', 3),

-- Q18: medium / L3 — Suspended passive losses released on full disposition
(3, 'Partnerships', 'Partner Navarro has $120,000 of suspended passive losses from Riverton Partners LP accumulated over several years. She does not materially participate and has no other passive income. In 2026, Navarro sells her entire partnership interest in a fully taxable transaction for a $50,000 gain. Apply the passive activity rules to determine the net deductible amount.', '["$50,000 gain only; the suspended losses remain suspended", "$120,000 loss deduction; the $50,000 gain is ignored", "Net loss of $0; suspended losses and gain exactly offset", "Net deduction of $70,000 against nonpassive income after offsetting the $50,000 gain"]'::jsonb, 3, 'Under IRC Section 469(g)(1), when a taxpayer disposes of an entire interest in a passive activity in a fully taxable transaction, all accumulated suspended passive losses are released and deductible. Navarro''s $120,000 of suspended losses is freed upon sale. After offsetting the $50,000 gain, the remaining $70,000 is deductible against nonpassive income. Partial dispositions do not trigger this full release of suspended losses.', 'medium', 3),

-- Q19: medium / L2 — Section 444 election for fiscal year-end
(3, 'Partnerships', 'Meridian Partners LP has three equal calendar-year individual partners and wants to adopt a September 30 fiscal year. The required taxable year under Section 706(b) is the calendar year. Under Section 444, what must the partnership do to use the September 30 year-end?', '["File Form 8716 and make required payments under Section 7519 to approximate the tax deferral benefit", "Obtain a private letter ruling from the IRS approving the fiscal year", "File Form 8832 to elect entity classification with a fiscal year", "Simply adopt the fiscal year on its first Form 1065 without any additional requirements"]'::jsonb, 0, 'Under IRC Section 444, a partnership may elect a taxable year other than its required year if the deferral period does not exceed three months. The partnership must file Form 8716 and make annual required payments under Section 7519 that approximate the tax deferral benefit the partners receive from the fiscal year. A private letter ruling is an alternative under Section 706(b)(1)(C) for a business purpose year, but Section 444 is the statutory elective path.', 'medium', 2),

-- Q20: medium / L2 — Guaranteed payment timing rules
(3, 'Partnerships', 'On December 15, 2026, Pinehurst Partners LP accrues a $50,000 guaranteed payment to Partner Oliver for management services. The partnership uses the accrual method with a calendar year-end. Oliver, a cash-method taxpayer, does not receive the payment until January 20, 2027. In which year does Oliver report the guaranteed payment income?', '["2026, the year the partnership deducts the payment", "2027, the year Oliver actually receives the cash", "Split equally between 2026 and 2027", "Whichever year Oliver elects on her individual return"]'::jsonb, 0, 'Under IRC Section 707(c) and Treas. Reg. Section 1.707-1(c), guaranteed payments are included in the partner''s income for the partnership taxable year in which the partnership deducts or accounts for them—regardless of the partner''s own accounting method. Because Pinehurst deducts the payment in its 2026 taxable year, Oliver must include the $50,000 in her 2026 income even though she received cash in January 2027.', 'medium', 2),

-- Q21: medium / L2 — Partner acting in non-partner capacity under Section 707(a)(1)
(3, 'Partnerships', 'Partner Quinn, a licensed attorney, performs legal services for Cedarwood Partners LP in connection with a real estate acquisition. Quinn bills the partnership $15,000 at her standard hourly rate—the same rate she charges unrelated clients. The payment is not determined by reference to partnership income. Under Section 707(a), how is this payment treated?', '["As a guaranteed payment subject to self-employment tax", "As a distribution reducing Quinn''s outside basis", "As a tax-free fringe benefit", "As a payment to a non-partner, deductible by the partnership and reported as ordinary income by Quinn"]'::jsonb, 3, 'Under IRC Section 707(a)(1), when a partner transacts with the partnership in a capacity other than as a partner (e.g., as an independent service provider at arm''s-length rates), the transaction is treated as between the partnership and a third party. Because Quinn billed at arm''s length and the payment was not tied to partnership income, it is a Section 707(a) transaction, not a guaranteed payment under Section 707(c).', 'medium', 2),

-- Q22: medium / L2 — Separately stated items on Schedule K-1
(3, 'Partnerships', 'Creekside Partners LP reports for 2026: $200,000 ordinary business income, $25,000 long-term capital gains, $8,000 of Section 1231 gains, $5,000 of charitable contributions, and $3,000 of tax-exempt interest. Which items must be separately stated on each partner''s Schedule K-1?', '["Only the $25,000 long-term capital gains and $5,000 charitable contributions", "The long-term capital gains, Section 1231 gains, charitable contributions, and tax-exempt interest", "All five items must be separately stated", "None—all items are combined into a single net income figure"]'::jsonb, 1, 'Under IRC Section 702(a), items whose character could affect a partner''s individual tax liability must be separately stated on Schedule K-1. Long-term capital gains (preferential rates), Section 1231 gains (recapture rules), charitable contributions (AGI limitations), and tax-exempt interest (affects other computations) all require separate reporting. Ordinary business income is the nonseparately stated residual item under Section 702(a)(8).', 'medium', 2),

-- Q23: hard / L4 — Mixing bowl transactions under Sections 704(c)(1)(B) and 737
(3, 'Partnerships', 'In 2020, Porter contributed land with a basis of $50,000 and FMV of $200,000 to an equal three-person partnership. In 2025, within the seven-year window, the partnership distributes different property worth $180,000 (inside basis $90,000) to Porter and distributes Porter''s original land to Partner Valle. Evaluate the tax consequences to Porter.', '["$90,000 gain under Section 737 only", "$150,000 gain under Section 704(c)(1)(B) only", "Gain under both provisions—$130,000 under Section 737 and $150,000 under 704(c)(1)(B), but Section 737(c)(1) reduces the 704(c)(1)(B) gain by the Section 737 amount to prevent double counting", "No gain because both distributions are nontaxable under Section 731"]'::jsonb, 2, 'Under IRC Section 737, Porter recognizes gain equal to the lesser of net precontribution gain ($150,000) or excess of distributed property FMV over outside basis ($180,000 - $50,000 = $130,000). Under Section 704(c)(1)(B), distributing Porter''s land to Valle triggers the remaining $150,000 built-in gain. However, Section 737(c)(1) reduces the 704(c)(1)(B) amount by gain already recognized under Section 737 to prevent double taxation in these ''mixing bowl'' transactions.', 'hard', 4),

-- Q24: medium / L2 — Partnership anti-abuse rule
(3, 'Partnerships', 'Under Treas. Reg. Section 1.701-2, when may the IRS recast a partnership transaction under the partnership anti-abuse rule?', '["Only when a partnership fails to file Form 1065 on time", "When a transaction is structured to achieve a tax result inconsistent with the intent of Subchapter K and lacks a substantial business purpose", "Only when a partnership has more than 100 partners", "Only when all partners are related parties under Section 267"]'::jsonb, 1, 'Under Treas. Reg. Section 1.701-2, the IRS may recast a partnership transaction if it was formed or used in connection with a transaction that achieves a tax result inconsistent with the intent of Subchapter K and lacks a substantial business purpose. This broad anti-abuse rule applies regardless of the number of partners or whether they are related—it focuses on whether the partnership form is being used to circumvent the purpose of the partnership tax rules.', 'medium', 2),

-- Q25: medium / L2 — Capital account maintenance requirements
(3, 'Partnerships', 'Silverleaf Partners LP wants its special allocations to satisfy the economic effect test under Treas. Reg. Section 1.704-1(b)(2)(ii). Which of the following is one of the three required elements?', '["Capital accounts must be maintained in accordance with the Treasury Regulations", "Each partner must have an outside basis exceeding $100,000", "The partnership must have at least four partners", "The partnership must use the cash method of accounting"]'::jsonb, 0, 'Under Treas. Reg. Section 1.704-1(b)(2)(ii)(b), proper maintenance of capital accounts is one of three requirements for economic effect. The other two are that liquidating distributions must follow positive capital account balances, and partners must have a deficit restoration obligation (or satisfy the alternate economic effect test). The number of partners, minimum basis, and accounting method are not factors in this test.', 'medium', 2),

-- Q26: hard / L4 — Mandatory 743(b) adjustment for substantial built-in loss
(3, 'Partnerships', 'Hawthorne Partners LP does not have a Section 754 election in effect. Partner Adler purchases a 50% interest for $300,000 when the partnership''s total inside basis is $1,000,000 (Adler''s 50% share = $500,000). No Section 754 election is filed. Evaluate whether a mandatory basis adjustment applies and its amount.', '["No adjustment because no Section 754 election was made", "A $200,000 step-up because Adler paid less than her share of inside basis", "A mandatory $200,000 step-down applies under Section 743(b) because the built-in loss exceeds $250,000", "A mandatory $200,000 step-down applies because Adler''s outside basis ($300,000) is less than her share of inside basis ($500,000) by more than $250,000"]'::jsonb, 2, 'Under IRC Section 743(d), even without a Section 754 election, a mandatory basis adjustment is required when a partnership has a substantial built-in loss—meaning the partnership''s total inside basis exceeds the FMV of its assets by more than $250,000. Because the partnership''s total inside basis ($1,000,000) implies the total FMV is only $600,000 (based on Adler''s 50% for $300,000), the built-in loss of $400,000 exceeds the $250,000 threshold, triggering a mandatory $200,000 step-down for Adler.', 'hard', 4),

-- Q27: hard / L4 — Section 736(a) vs (b) classification for retiring general partner
(3, 'Partnerships', 'Partner Pryor retires from a three-person general partnership. The partnership agreement does not mention goodwill. The partnership pays Pryor $250,000: $160,000 for his share of partnership assets (including $30,000 attributable to goodwill) and $90,000 for past services. Under Section 736, evaluate how the payments are classified.', '["$130,000 under Section 736(b) for assets excluding goodwill, $30,000 under Section 736(a) for unstated goodwill, and $90,000 under Section 736(a) for services", "$250,000 entirely under Section 736(b) as payments for partnership property", "$160,000 under Section 736(b) and $90,000 under Section 736(a)", "$250,000 entirely under Section 736(a) as distributive share"]'::jsonb, 0, 'Under IRC Section 736(b)(2)(B), for a general partnership, payments for goodwill are classified under Section 736(b) only if the partnership agreement specifically provides for goodwill payments. Since the agreement is silent on goodwill, the $30,000 attributable to goodwill falls under Section 736(a) (ordinary income to Pryor, deductible by the partnership). The $130,000 for other assets is under Section 736(b), and the $90,000 for services is Section 736(a).', 'hard', 4),

-- Q28: easy / L1 — Check-the-box entity classification for partnerships
(3, 'Partnerships', 'Under the check-the-box regulations, how is a domestic multi-member LLC classified for federal tax purposes if no election is filed?', '["C corporation", "S corporation", "Partnership", "Disregarded entity"]'::jsonb, 2, 'Under Treas. Reg. Section 301.7701-3(b)(1), a domestic eligible entity with two or more members is classified as a partnership by default unless it elects to be treated as a corporation by filing Form 8832. This default classification means a multi-member LLC files Form 1065 and issues Schedule K-1s to its members without any affirmative election.', 'easy', 1),

-- Q29: medium / L3 — Tiered partnerships: distributive share from lower-tier partnership
(3, 'Partnerships', 'Alpine Partners LP (upper-tier) owns a 40% interest in Summit Partners LP (lower-tier). Summit earns $200,000 of ordinary income and $50,000 of long-term capital gains. Partner Doyle is a 25% partner in Alpine. Apply the tiered partnership rules to determine how Summit''s income flows to Doyle.', '["Doyle reports his share as entirely ordinary income because it passes through an entity", "Doyle reports 25% of Alpine''s 40% share, preserving character: $20,000 ordinary income and $5,000 long-term capital gains", "Doyle reports only the income Alpine actually distributes in cash", "Doyle reports 40% of Summit''s total income directly"]'::jsonb, 1, 'Under IRC Section 702(b), the character of partnership items is determined at the partnership level and retains its character as it flows through to partners. In tiered partnerships, Alpine''s 40% share of Summit''s income is $80,000 ordinary and $20,000 LTCG. Doyle''s 25% share of Alpine''s items is $20,000 ordinary and $5,000 LTCG. The character is preserved through each tier; it does not convert to ordinary income merely by passing through multiple entities.', 'medium', 3),

-- Q30: medium / L2 — Basis ordering: increases before decreases
(3, 'Partnerships', 'Partner Voss has a beginning outside basis of $10,000. During the year, her distributive share includes $30,000 of ordinary income, a $5,000 distribution, and a $25,000 ordinary loss. Under the basis ordering rules, what is Voss''s ending outside basis?', '["$10,000", "$5,000", "$15,000", "$20,000"]'::jsonb, 0, 'Under IRC Section 705(a), basis increases (income allocations) are applied before basis decreases (distributions and losses). Starting at $10,000, Voss adds the $30,000 income to reach $40,000. Then the $5,000 distribution reduces basis to $35,000. Finally, the $25,000 loss reduces basis to $10,000. The ordering matters because applying decreases first could incorrectly limit the allowable loss deduction or trigger gain recognition on the distribution.', 'medium', 2)
;

COMMIT;
